    _ = _accelerator  # keep alive

    # Create and run trainer
    trainer = Trainer(
        model=model,
        args=training_args,
        train_dataset=ds,
        eval_dataset=eval_ds,
        data_collator=collator,
        compute_metrics=_compute_metrics if eval_ds is not None else None,
        callbacks=callbacks,
    )
