    # Optionally split dataset
    train_texts = texts
    if val_texts is None and val_split > 0:
        train_texts, val_texts = split_dataset(
            texts, train_ratio=1 - val_split, seed=seed, cache_path=split_cache
        )

    # Prepare datasets
