    dtype: str = "fp32",
    deterministic: Optional[bool] = None,
    gradient_accumulation_steps: int = 1,
    checkpoint_dir: Optional[Path] = None,
    save_steps: int = 100,
    keep_last: int = 3,
    best_metric: Optional[str] = "eval_loss",
    best_mode: str = "min",
    seed: int = 0,
    resume_from: Optional[str] = None,
    val_texts: Optional[Iterable[str]] = None,
    val_split: float = 0.0,
