    lora_task_type: Optional[str] = None,
    precision: Optional[str] = None,
    device: str = "auto",
    dtype: str = "fp32",
    deterministic: Optional[bool] = None,
    gradient_accumulation_steps: int = 1,
    checkpoint_dir: Optional[Path] = None,
    save_steps: int = 100,
    keep_last: int = 3,
    best_metric: Optional[str] = "eval_loss",
    best_mode: str = "min",
