    (output_dir / "resume_manifest.json").write_text(
        json.dumps(manifest, indent=2, sort_keys=True), encoding="utf-8"
    )

    _log_mlflow_metrics(
        metrics,
        training_args,
        model_name=model_name,
        tracking_uri=mlflow_tracking_uri,
        log_args=log_args,
    )

    return metrics


