                def on_step_end(self, args, state, control, **kwargs):
                    step = state.global_step
                    if (
                        step
                        and save_steps
                        and step % save_steps == 0
                        and self.model is not None
                        and self.optimizer is not None
                    ):
                        payload = build_payload_bytes(
                            None,
                            self.optimizer,
                            self.lr_scheduler,
                            self.scaler,
                            rng_state=True,
                        )
