    trainer.save_model()

    # Collect metrics
    metrics = dict(result.metrics)
    if eval_ds is not None:
        eval_metrics = trainer.evaluate()
        metrics.update({f"eval_{k}": v for k, v in eval_metrics.items()})
    metrics.setdefault("global_step", trainer.state.global_step)

    # Codex offline logging
    if sys_metrics:
        try:
            sysd = _codex_sample_system()
            log_vals = {
                **{k: v for k, v in metrics.items() if isinstance(v, (int, float))},
                **sysd,
            }
            _codex_log_all(int(metrics.get("global_step", 0)), log_vals, loggers)
        except Exception as e:
            logger.debug(f"Exception: {e}")
            logger.warning(f"Exception: {e}", )  # Logging failure; continue with training

    # TensorBoard logging
    if tensorboard and SummaryWriter is not None:
        try:
            writer = SummaryWriter(log_dir=str(output_dir / "tensorboard"))
            for k, v in metrics.items():
                if isinstance(v, (int, float)):
                    writer.add_scalar(k, v, trainer.state.global_step)
            writer.flush()
            writer.close()
        except Exception as e:
            logger.debug(f"Exception: {e}")
            logger.warning(f"Exception: {e}", exc_info=True)  # TensorBoard logging failure; continue with training

