    if model is None:
        model_kwargs: dict[str, Any] = {}
        if not _looks_like_local_source(model_name):
            model_kwargs["revision"] = get_hf_revision(model_name)
        model = load_from_pretrained(
            AutoModelForCausalLM,
            model_name,
            **model_kwargs,
        )

