    source = tokenizer_path or tokenizer_name
    tokenizer_kwargs: dict[str, Any] = {"use_fast": use_fast_tokenizer}
    if not _looks_like_local_source(source):
        tokenizer_kwargs["revision"] = get_hf_revision(source)
